window.products.push({"id":148227,"name":"General Electric GVK8HS Ducting Kit, White","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71Ne8OXvM+L._AC_SL1500_.jpg","description":"The GeoSpring ducting kit provides flexibility of installation in living areas and confined spaces for maximum comfort. Consisting of an inlet duct adapter with filter, an outlet duct adapter, and associated hardware this kit makes it possible to install GeoSpring where the total volume of air recommended for non-ducted GeoSpring installations (10'x10'x7') may not be available. Additionally, the kit provides a way for the installer to draw or exhaust air into locations that may provide additional benefit to the home, or to draw air from and exhaust air to the outside of the home.","images":["https://m.media-amazon.com/images/I/71Ne8OXvM+L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"GE","source_asin":"B00W5B0MYG","category_path":"Home & Appliances"},"sku":"BM-148227","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00W5B0MYG","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Appliances.jsonl","source_asin":"B00W5B0MYG","price_pending":true,"merchant_ready":false});
